  group('SigintPolicy (issue #830 double-press contract)', () {
    late List<FakeStopwatch> clocks;
    late FakeStopwatch clock;

    setUp(() {
      clocks = [];
      clock = FakeStopwatch(clocks); // registered first, for advanceAll
    });

