        // VM flags go BEFORE the script path.
        if (vmServicePort != null) ...[
          '--disable-service-auth-codes',
          '--observe=$vmServicePort',
        ],
        '${Directory.current.path}/bin/fah.dart',
      ],
      ...args,
    ],
    workingDirectory: ownedCwd?.path ?? workingDirectory,
    environment: env,
    raw: raw,
  );
