      const stillAlive = -999;
      final code = await harness.pty.exitCode.timeout(
        const Duration(seconds: 30),
        onTimeout: () => stillAlive,
      );
      expect(
        code,
        isNot(stillAlive),
        reason:
            'press 2 inside the fresh window must exit the REPL '
            '(issue #830); exit code $code',
      );
    });
  });

